('QUA_HAN','nhiem_vu_qua_han','T9/2026','02',8,2,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Rà soát, phân loại các đề xuất, kiến nghị của Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội; chủ động xem xét, xử lý theo thẩm quyền. Đối với nội dung vượt thẩm quyền, báo cáo cấp có thẩm quyền xem xét, quyết định. Kết quả rà soát, xử lý được tổng hợp trong Báo cáo tổng thể trình Ban Thường vụ Thành ủy.", "co_quan_chu_tri": "UBND Thành phố", "han": "2026-08-15", "moc_kiem_tra": "01/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','03',8,3,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Tham mưu đồng chí Phó Bí thư Thành ủy chỉ đạo các đồng chí Bí thư Đảng ủy 126 xã, phường tập trung lãnh đạo, chỉ đạo thực hiện làm sạch dữ liệu đất đai. Kết quả thực hiện đến ngày 30/8/2026 được đối chiếu với KPI đã được thông báo đến từng xã, phường và sử dụng làm căn cứ đánh giá kết quả thực hiện nhiệm vụ, trách nhiệm người đứng đầu trong quý III/2026.", "co_quan_chu_tri": "Văn phòng Thành ủy", "han": "2026-08-30", "moc_kiem_tra": "02/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','04',8,4,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Các sở, ngành lựa chọn, đăng ký từ 01-02 sản phẩm cụ thể gắn với phát triển kinh tế số của ngành, lĩnh vực; hoàn thành đăng ký trong đầu tháng 9/2026 để làm cơ sở kiểm đếm, đánh giá kết quả thực hiện vào cuối năm.", "co_quan_chu_tri": "Sở, ngành Thành phố", "han": "2026-09-15", "moc_kiem_tra": "02/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','05',8,5,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Phê duyệt hồ sơ đề xuất cấp độ an toàn hệ thống thông tin đối với các hệ thống trước khi đưa vào vận hành, khai thác; tổ chức kiểm tra, đánh giá an ninh mạng định kỳ.", "co_quan_chu_tri": "Các sở, ban, ngành Thành phố và UBND xã, phường", "han": "2026-08-15", "moc_kiem_tra": "01/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','06',8,6,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Các sở, ban, ngành rà soát, chuẩn hóa, hoàn thiện các cơ sở dữ liệu chuyên ngành thuộc phạm vi quản lý, bảo đảm dữ liệu đúng, đủ, sạch, sống, thống nhất, dùng chung, kết nối và chia sẻ được; hoàn thành trước ngày 30/8/2026. Sở Khoa học và Công nghệ chủ trì hướng dẫn tiêu chuẩn kỹ thuật, kiến trúc dữ liệu, kết nối, chia sẻ dữ liệu; bảo đảm đồng bộ, thống nhất trong xây dựng, chia sẻ, tích hợp dữ liệu của các cơ quan, đơn vị.", "co_quan_chu_tri": "Các sở, ban, ngành Thành phố", "han": "2026-08-30", "moc_kiem_tra": "02/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','07',8,7,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Phân công đồng chí Trương Việt Dũng, Thành ủy viên, Phó Chủ tịch UBND Thành phố trực tiếp chỉ đạo Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội chủ trì, phối hợp với các cơ quan, đơn vị liên quan xây dựng Báo cáo tổng thể về định hướng, nhiệm vụ và giải pháp phát triển Khu công nghệ cao Hòa Lạc trong giai đoạn mới; báo cáo Ban Thường vụ Thành ủy. Báo cáo tập trung làm rõ: Kết quả thực hiện các kết luận, chỉ đạo liên quan; tồn tại, hạn chế, nguyên nhân, trách nhiệm và những nội dung cần thay đổi trong phương thức tổ chức thực hiện. Vị trí, vai trò, mục tiêu, định hướng và mô hình phát triển Khu công nghệ cao Hòa Lạc trong tổng thể phát triển khu vực phía Tây Thành phố. Việc rà soát quy hoạch Khu công nghệ cao Hòa Lạc với quy mô hiện có 1.586 ha và phạm vi mở rộng 460 ha, tổng quy mô 2.046 ha; việc kết nối với Đại học Quốc gia Hà Nội, các trường đại học, viện nghiên cứu, hệ thống giao thông, các khu đô thị, đô thị thông minh và không gian phát triển xung quanh. Lợi thế cạnh tranh thực chất của Khu Công nghệ cao Hòa Lạc so với các điểm đến đầu tư cạnh tranh trong khu vực; giải pháp thu hút nhà đầu tư có chất lượng, nhất là nhà đầu tư lớn, doanh nghiệp dẫn dắt có khả năng kéo hệ sinh thái, doanh nghiệp vệ tinh, chuỗi cung ứng, nhân lực chất lượng cao, trung tâm nghiên cứu và phát triển vào Hòa Lạc; đề xuất chính sách đặc biệt đủ sức cạnh tranh, gắn với ràng buộc cụ thể về vốn, công nghệ, tiến độ, hiệu quả sử dụng đất và mức độ đóng góp cho hệ sinh thái. Kết quả rà soát các dự án đã được chấp thuận và các dự án đang nghiên cứu, chuẩn bị đầu tư; năng lực nhà đầu tư, tiến độ thực hiện, hiệu quả sử dụng đất, mức độ đáp ứng tiêu chí công nghệ cao và phương án xử lý theo quy định đối với các dự án không triển khai, chậm triển khai, sử dụng đất kém hiệu quả hoặc không còn đáp ứng tiêu chí. Kết quả rà soát các cơ chế, chính sách, quy định và thủ tục hành chính liên quan đến hoạt động của Khu công nghệ cao Hòa Lạc; mô hình quản lý, vận hành, khai thác và phương án tổ chức bộ máy phù hợp, bảo đảm hoạt động hiệu lực, hiệu quả.", "co_quan_chu_tri": "Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội", "han": "2026-08-15", "moc_kiem_tra": "02/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','08',8,8,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Chủ trì, phối hợp với các cơ quan liên quan xây dựng phương án cung cấp thiết bị công nghệ thông tin cho các cơ quan trong hệ thống chính trị Thành phố (Thành ủy, HĐND, UBND Thành phố, Ủy ban MTTQ Việt Nam Thành phố và các sở, ban, ngành), bảo đảm đồng bộ, hiệu quả, tránh chồng chéo, dàn trải, lãng phí; hoàn thành trước ngày 20/3/2026.", "co_quan_chu_tri": "Sở Khoa học và Công nghệ", "han": "2026-03-20", "moc_kiem_tra": "02/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
('QUA_HAN','nhiem_vu_qua_han','T9/2026','09',8,9,NULL,NULL,'Nhiệm vụ quá hạn','Nhiệm vụ quá hạn','nhiệm vụ',NULL,0,NULL,NULL,NULL,NULL,1.0,1,'BC tháng 9/2026 - Phụ lục 02, mục I (chốt 17h00 25/9/2026)',NULL,NULL,NULL,NULL,NULL,'{"ten": "Đồng chí Nguyễn Xuân Lưu, Ủy viên Ban Thường vụ Thành ủy, Phó Chủ tịch UBND Thành phố, Tổ phó Tổ công tác của Ban Thường vụ Thành ủy về sắp xếp các đơn vị sự nghiệp công lập, doanh nghiệp nhà nước trên địa bàn Thành phố trực tiếp chỉ đạo Công ty Cổ phần Hanel, Công ty TNHH một thành viên Chiếu sáng và Thiết bị đô thị, Công ty TNHH một thành viên Thoát nước Hà Nội và Công ty Cổ phần Giống gia súc Hà Nội hoàn thiện đề án phát triển doanh nghiệp trên cơ sở Nghị quyết 57 của Bộ Chính trị. Các đề án phải đánh giá đúng thực chất năng lực hiện có; xác định rõ định hướng phát triển, lộ trình thực hiện, tổ chức bộ máy, nhân lực và các kiến nghị, đề xuất với Thành phố; hoàn thành trước ngày 15/8/2026. Giao Sở Khoa học và Công nghệ chủ trì, phối hợp với các sở, ngành liên quan thẩm định, tham mưu UBND Thành phố báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 30/8/2026.", "co_quan_chu_tri": "Sở Khoa học và Công nghệ", "han": "2026-08-30", "moc_kiem_tra": "02/10/2026", "cho_trung_uong": false, "ngay_chot": "2026-09-25"}',@sync),
